<?php

namespace App\Http\Requests;

use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;

/**
 * Registers or edits a module of the catalog. The stable key is generated by the server and never edited. A module may be
 * filed under an active category (or keep the one it already has).
 */
class SaveModuleRequest extends FormRequest
{
    public function authorize(): bool
    {
        return true;
    }

    protected function prepareForValidation(): void
    {
        $this->merge([
            'name' => trim((string) $this->input('name')),
            'description' => ($description = trim((string) $this->input('description'))) === '' ? null : $description,
        ]);
    }

    /** @return array<string, mixed> */
    public function rules(): array
    {
        $current = $this->route('module');

        return [
            'name' => ['required', 'string', 'max:120', Rule::unique('modules', 'name')->ignore($current)],
            'description' => ['nullable', 'string', 'max:500'],
            'module_category_id' => ['required', 'integer', Rule::exists('module_categories', 'id')->where(
                fn ($query) => $query->where('is_active', true)->when($current, fn ($q) => $q->orWhere('id', $current->module_category_id)),
            )],
        ];
    }
}
